mapper.select:
        select
        (
            select count(1) as personnelNum
            from (
                select t.staff_personnel_id, t.user_id
                from (
                    select staff_personnel_id,real_name,user_id from staff_pay_personnel_slip where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                    UNION all
                    select staff_personnel_id,real_name,user_id from staff_performance_personnel where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                ) t left join staff_personnel_info info on t.staff_personnel_id = info.id
                group by t.user_id
            ) c
        )  as personnelNum
,

        (
            select count(1) as personnelNum
            from (
                select t.staff_personnel_id, t.user_id
                    from (
                        select staff_personnel_id,real_name,user_id from staff_pay_personnel_slip where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                        UNION all
                        select staff_personnel_id,real_name,user_id from staff_performance_personnel where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                    ) t
                left join staff_personnel_info info on t.staff_personnel_id = info.id
                where info.entry_time <= #{startTime,jdbcType=VARCHAR}
                and (info.quit_time is null or (info.quit_time is not null and info.staff_state!=6 and info.quit_time <= #{startTime,jdbcType=VARCHAR}))
                group by t.user_id
            ) c
        ) as monthBeginPersonnelNum
,

        (
            select count(1) as personnelNum
              from (
                select t.staff_personnel_id, t.user_id
                from (
                select staff_personnel_id,real_name,user_id from staff_pay_personnel_slip where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                UNION all
                select staff_personnel_id,real_name,user_id from staff_performance_personnel where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                ) t
                left join staff_personnel_info info on t.staff_personnel_id = info.id
                where info.entry_time <= #{monthEndTime,jdbcType=VARCHAR} and info.quit_time is null
                group by t.user_id
            ) c
        ) as monthEndPersonnelNum
,
        (
            select count(1) as personnelNum
            from (
            select t.staff_personnel_id, t.user_id
                from (
                select staff_personnel_id,real_name,user_id from staff_pay_personnel_slip where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                UNION all
                select staff_personnel_id,real_name,user_id from staff_performance_personnel where work_time >= #{startTime,jdbcType=VARCHAR} AND work_time <= #{endTime,jdbcType=VARCHAR} and delete_flag=0 
                ) t
            left join staff_personnel_info info on t.staff_personnel_id = info.id
            where info.quit_time >= #{startTime,jdbcType=VARCHAR} and info.quit_time <= #{monthEndTime,jdbcType=VARCHAR}
            group by t.user_id
            ) c
        ) as quitPersonnelNum
